export async function waitFor(condition, timeout = 5000, interval = 100) {
  const start = Date.now();
  while (Date.now() - start < timeout) {
    if (await condition()) return true;
    await new Promise(resolve => setTimeout(resolve, interval));
  }
  throw new Error('Timeout waiting for condition');
}

import bcrypt
import secrets
import hashlib
from typing import Optional

class PasswordHasher:
    def __init__(self, rounds: int = 12):
        self.rounds = rounds

    def hash(self, password: str) -> str:
        salt = bcrypt.gensalt(rounds=self.rounds)
        hashed = bcrypt.hashpw(password.encode('utf-8'), salt)
        return hashed.decode('utf-8')

    def verify(self, password: str, hashed: str) -> bool:
        try:
            return bcrypt.checkpw(
                password.encode('utf-8'),
                hashed.encode('utf-8')
            )
        except Exception:
            return False

    def generate_reset_token(self) -> str:
        return secrets.token_urlsafe(32)

    def hash_token(self, token: str) -> str:
        return hashlib.sha256(token.encode()).hexdigest()

    def verify_token(self, token: str, hashed: str) -> bool:
        return secrets.compare_digest(self.hash_token(token), hashed)

hasher = PasswordHasher()
hashed = hasher.hash('secure_password123')
is_valid = hasher.verify('secure_password123', hashed)

import time
import functools
from typing import Callable
import logging

def profile(func: Callable = None, *, threshold: float = 1.0):
    def decorator(func: Callable):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            start = time.perf_counter()
            result = func(*args, **kwargs)
            end = time.perf_counter()
            elapsed = end - start

            if elapsed > threshold:
                logging.warning(
                    f"Slow function: {func.__name__} "
                    f"took {elapsed:.3f}s (threshold: {threshold}s)"
                )

            return result
        return wrapper

    if func:
        return decorator(func)
    return decorator

def count_calls(func: Callable):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        wrapper.call_count += 1
        return func(*args, **kwargs)
    wrapper.call_count = 0
    return wrapper

@profile(threshold=0.5)
def slow_function():
    time.sleep(0.6)

@count_calls
def my_function():
    pass

export const dateUtils = {
  format(date, format = 'YYYY-MM-DD') {
    const d = new Date(date);
    const year = d.getFullYear();
    const month = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    const hours = String(d.getHours()).padStart(2, '0');
    const minutes = String(d.getMinutes()).padStart(2, '0');
    const seconds = String(d.getSeconds()).padStart(2, '0');

    return format
      .replace('YYYY', year)
      .replace('MM', month)
      .replace('DD', day)
      .replace('HH', hours)
      .replace('mm', minutes)
      .replace('ss', seconds);
  },

  addDays(date, days) {
    const result = new Date(date);
    result.setDate(result.getDate() + days);
    return result;
  },

  isBetween(date, start, end) {
    const d = new Date(date).getTime();
    return d >= new Date(start).getTime() && d <= new Date(end).getTime();
  },

  diffDays(date1, date2) {
    const msPerDay = 24 * 60 * 60 * 1000;
    return Math.floor(Math.abs(date1 - date2) / msPerDay);
  },

  startOfDay(date) {
    const d = new Date(date);
    d.setHours(0, 0, 0, 0);
    return d;
  },

  endOfDay(date) {
    const d = new Date(date);
    d.setHours(23, 59, 59, 999);
    return d;
  }
};

