export const xssUtils = {
  escapeHtml(text) {
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
  },

  sanitizeHtml(html, allowedTags = []) {
    const parser = new DOMParser();
    const doc = parser.parseFromString(html, 'text/html');

    const removeTags = (node) => {
      if (node.nodeType === Node.ELEMENT_NODE) {
        if (!allowedTags.includes(node.tagName.toLowerCase())) {
          node.replaceWith(...node.childNodes);
          return;
        }

        for (const attr of [...node.attributes]) {
          if (attr.name.startsWith('on') || attr.name === 'style') {
            node.removeAttribute(attr.name);
          }
        }
      }

      for (const child of [...node.childNodes]) {
        removeTags(child);
      }
    };

    removeTags(doc.body);
    return doc.body.innerHTML;
  },

  validateUrl(url) {
    try {
      const parsed = new URL(url);
      return ['http:', 'https:'].includes(parsed.protocol);
    } catch {
      return false;
    }
  }
};

function VirtualList({ items, itemHeight, containerHeight }) {
  const [scrollTop, setScrollTop] = useState(0);

  const visibleCount = Math.ceil(containerHeight / itemHeight);
  const startIndex = Math.floor(scrollTop / itemHeight);
  const endIndex = Math.min(startIndex + visibleCount, items.length);

  const visibleItems = items.slice(startIndex, endIndex);
  const totalHeight = items.length * itemHeight;
  const offsetTop = startIndex * itemHeight;

  return (
    <div
      style={{ height: containerHeight, overflow: 'auto' }}
      onScroll={e => setScrollTop(e.target.scrollTop)}
    >
      <div style={{ height: totalHeight, position: 'relative' }}>
        <div style={{ position: 'absolute', top: offsetTop }}>
          {visibleItems.map((item, index) => (
            <div
              key={startIndex + index}
              style={{ height: itemHeight }}
            >
              {item}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

import os
import json
from pathlib import Path
from typing import Any, Dict
from dotenv import load_dotenv

class ConfigLoader:
    def __init__(self, env: str = None):
        self.env = env or os.getenv('ENV', 'development')
        self.config: Dict[str, Any] = {}
        load_dotenv(f'.env.{self.env}')

    def load(self) -> Dict[str, Any]:
        self.config = {
            'env': self.env,
            'debug': self.env == 'development',
            'database': {
                'url': os.getenv('DATABASE_URL'),
                'pool_size': int(os.getenv('DB_POOL_SIZE', '10'))
            },
            'redis': {
                'url': os.getenv('REDIS_URL'),
            },
            'jwt': {
                'secret': os.getenv('JWT_SECRET'),
                'expires': int(os.getenv('JWT_EXPIRES', '3600'))
            },
            'logging': {
                'level': os.getenv('LOG_LEVEL', 'INFO')
            }
        }
        return self.config

    def get(self, key: str, default: Any = None) -> Any:
        keys = key.split('.')
        value = self.config
        for k in keys:
            if isinstance(value, dict):
                value = value.get(k)
            else:
                return default
        return value if value is not None else default

